	static long mod = 998244353;

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		long n = sc.nextLong();
		long m = sc.nextLong();
		long L = sc.nextLong();
		long R = sc.nextLong();
		long h = R-L;

		long evenCount = 0;
		long oddCount = 0;
		if(h % 2 == 1){
			long d = (h+1)/2;
			evenCount = d;
			oddCount = d;
		}
		else{
			long d = h/2;
			evenCount = d;
			oddCount = d;
			if(L % 2 == 1) oddCount++;
			else evenCount++;
		}

		long[][] transition = {{evenCount, oddCount},{oddCount, evenCount}};
		long[][] resultMatrix = matrixPower(transition, m*n);
		long total = resultMatrix[0][0];
		if((n*m)%2==1) total += resultMatrix[0][1];
		System.out.println(total % mod);
