#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

vector<vector<long long>> matrixMultiply(const vector<vector<long long>>& a, const vector<vector<long long>>& b) {
    int n = a.size();
    int m = b[0].size();
    int p = a[0].size();
    vector<vector<long long>> res(n, vector<long long>(m, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            for (int k = 0; k < p; k++) {
                res[i][j] += (a[i][k] % mod) * (b[k][j] % mod);
                res[i][j] %= mod;
            }
        }
    }
    return res;
}

vector<vector<long long>> matrixPower(vector<vector<long long>> base, long long power) {
    int size = base.size();
    vector<vector<long long>> result(size, vector<long long>(size, 0));
    for (int i = 0; i < size; i++) {
        result[i][i] = 1;
    }
    while (power > 0) {
        if (power % 2 == 1) {
            result = matrixMultiply(result, base);
        }
        base = matrixMultiply(base, base);
        power /= 2;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, L, R;
    cin >> n >> m >> L >> R;
    long long h = R - L;
    long long evenCount = 0;
    long long oddCount = 0;
    if (h % 2 == 1) {
        long long d = (h + 1) / 2;
        evenCount = d;
        oddCount = d;
    } else {
        long long d = h / 2;
        evenCount = d;
        oddCount = d;
        if (L % 2 == 1) oddCount++;
        else evenCount++;
    }

    vector<vector<long long>> transition = {
        {evenCount, oddCount},
        {oddCount, evenCount}
    };

    vector<vector<long long>> resultMatrix = matrixPower(transition, m * n);
    long long total = resultMatrix[0][0];
    if ((n * m) % 2 == 1) total += resultMatrix[0][1];
    cout << total % mod << "\n";

    return 0;
}
